package com.savitar.rbc;
import android.app.*;
import android.content.*;
import android.media.*;
import android.media.session.*;
import android.os.*;

public class PlaybackService extends Service {
 public static PlaybackService instance;
 private MediaPlayer player;private MediaSession session;private AudioManager manager;private AudioFocusRequest focus;
 private String title="Ambiente RBC EASY",track="";private float volume=.18f;private boolean ducked=false,focusDuck=false,prepared=false,resumeOnFocusGain=false;
 private final BroadcastReceiver noisy=new BroadcastReceiver(){@Override public void onReceive(Context context,Intent intent){pausePlayback();}};
 private static final String CHANNEL="rbc-ambience";private static final int ID=2301;
 @Override public void onCreate(){super.onCreate();instance=this;if(Build.VERSION.SDK_INT>=33)registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));manager=(AudioManager)getSystemService(AUDIO_SERVICE);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel(CHANNEL,"Ambiente",NotificationManager.IMPORTANCE_LOW));session=new MediaSession(this,"RBC EASY");session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setCallback(new MediaSession.Callback(){@Override public void onPlay(){resumePlayback();}@Override public void onPause(){pausePlayback();}@Override public void onStop(){pausePlayback();}});session.setSessionActivity(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));session.setActive(true);AudioAttributes attributes=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build();focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(attributes).setOnAudioFocusChangeListener(change->{
 if(change==AudioManager.AUDIOFOCUS_LOSS){pausePlayback();}
 else if(change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT){resumeOnFocusGain=resumeOnFocusGain||isPlaying();if(resumeOnFocusGain)player.pause();updateState();}
 else {focusDuck=change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK;applyVolume();if(change==AudioManager.AUDIOFOCUS_GAIN&&resumeOnFocusGain&&player!=null&&prepared){resumeOnFocusGain=false;player.start();updateState();MediaPlugin.state(true);}}
}).build();}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent==null)return START_NOT_STICKY;String action=intent.getAction();if("TOGGLE".equals(action)){if(isPlaying())pausePlayback();else resumePlayback();return START_NOT_STICKY;}if("PLAY".equals(action)){title=intent.getStringExtra("title");ducked=intent.getBooleanExtra("ducked",false);volume=Math.max(0,Math.min(.4f,intent.getFloatExtra("volume",.18f)));startForeground(ID,notification());String next=intent.getStringExtra("id");if(next!=null&&next.equals(track)&&prepared){resumePlayback();return START_NOT_STICKY;}releasePlayer();track=next;try{player=new MediaPlayer();player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());player.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);player.setDataSource(intent.getStringExtra("path"));player.setLooping(true);player.setOnPreparedListener(value->{prepared=true;resumePlayback();});player.setOnErrorListener((value,what,extra)->{releasePlayer();MediaPlugin.state(false);stopForeground(true);stopSelf();return true;});player.prepareAsync();}catch(Exception error){releasePlayer();MediaPlugin.state(false);stopForeground(true);stopSelf();}}return START_NOT_STICKY;}
 public boolean isPlaying(){try{return player!=null&&prepared&&player.isPlaying();}catch(Exception error){return false;}}
 public void setAudioVolume(float value,boolean silence){volume=value;ducked=silence;applyVolume();}
 private void applyVolume(){if(player!=null){float value=ducked?0:focusDuck?volume*.2f:volume;try{player.setVolume(value,value);}catch(Exception ignored){}}}
 private void resumePlayback(){if(player==null||!prepared){MediaPlugin.state(false);return;}startForeground(ID,notification());if(manager.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){MediaPlugin.state(false);return;}applyVolume();player.start();updateState();MediaPlugin.state(true);}
 public void pausePlayback(){resumeOnFocusGain=false;if(isPlaying())player.pause();if(manager!=null&&focus!=null)manager.abandonAudioFocusRequest(focus);updateState();stopForeground(false);MediaPlugin.state(false);}
 private void updateState(){session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).putString(MediaMetadata.METADATA_KEY_ARTIST,"Ambiente · RBC EASY").build());session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_STOP).setState(isPlaying()?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,player!=null&&prepared?player.getCurrentPosition():0,1).build());((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(ID,notification());}
 private Notification notification(){Intent intent=new Intent(this,PlaybackService.class).setAction("TOGGLE");PendingIntent action=isPlaying()?PendingIntent.getService(this,0,intent,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT):PendingIntent.getForegroundService(this,0,intent,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,CHANNEL).setSmallIcon(com.savitar.rbc.R.drawable.ic_stat_audio).setContentTitle(title).setContentText("Ambiente · RBC EASY").setContentIntent(session.getController().getSessionActivity()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0)).addAction(new Notification.Action.Builder(android.graphics.drawable.Icon.createWithResource(this,isPlaying()?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play),isPlaying()?"Pausar":"Reproducir",action).build()).setOngoing(isPlaying()).setVisibility(Notification.VISIBILITY_PUBLIC).setOnlyAlertOnce(true).build();}
 private void releasePlayer(){prepared=false;if(player!=null){player.release();player=null;}}
 @Override public void onDestroy(){try{unregisterReceiver(noisy);}catch(Exception ignored){}releasePlayer();if(session!=null)session.release();if(manager!=null&&focus!=null)manager.abandonAudioFocusRequest(focus);instance=null;super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
